testExamples.bddWithAssertAll:
/**
 * Feature: Transaction Validation
 * Scenario: Validate all transaction fields
 *
 * Given: a transaction DTO with multiple fields
 * When: validating the transaction
 * Then:
 *  - all required fields are present
 *  - all fields have correct values
 *  - no validation errors occur
 */
@Test
@DisplayName("DADO un DTO completo CUANDO se valida ENTONCES todos los campos son correctos")
void validate_WithCompleteDTO_ShouldPassAllValidations() {
    // Arrange
    TransactionDTO dto = createTestTransaction();

    // Act & Assert
    assertAll("Transaction fields",
        () -> assertNotNull(dto.getCode(), "Code should not be null"),
        () -> assertEquals("Abono", dto.getType(), "Type should be Abono"),
        () -> assertTrue(dto.getAmount() > 0, "Amount should be positive")
    );
}

testExamples.bddWithGrouping:
/**
 * Feature: Batch Processing
 * Scenario: Group transactions by type and count them
 *
 * Given: multiple transactions of different types
 * When: grouping transactions by type
 * Then:
 *  - transactions are correctly grouped by type
 *  - count per type is accurate
 *  - no transactions are lost
 */
@Test
@DisplayName("DADO transacciones mixtas CUANDO se agrupan por tipo ENTONCES el conteo es correcto")
void process_WithMultipleTypes_ShouldGroupCorrectly() {
    // Arrange
    List<TransactionDTO> transactions = List.of(
        new TransactionDTO("T1", "Abono", 100.0),
        new TransactionDTO("T2", "Abono", 200.0),
        new TransactionDTO("T3", "Cargo", 150.0)
    );

    // Act
    Map<String, Long> grouped = transactions.stream()
        .collect(Collectors.groupingBy(
            TransactionDTO::getType,
            Collectors.counting()
        ));

    // Assert
    assertEquals(2L, grouped.get("Abono"));
    assertEquals(1L, grouped.get("Cargo"));
}

